content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-30-pet-feeder-002

=== 用户原始指令 (query.txt) ===
整个喂食卡吧，文字叠背景图上那种，点一下跳到app，读个天气

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个喂食卡吧，文字叠背景图上那种，点一下跳到app，读个天气",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县或当前位置展示名",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级",
            "sampleValue": "优"
          },
          "humidityPercent": {
            "type": "number",
            "description": "当前相对湿度百分比",
            "sampleValue": 66
          },
          "windLevel": {
            "type": "integer",
            "description": "当前风力等级",
            "sampleValue": 2
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/cloudy_turning_sunny.png",
      "description": "小云朵和太阳组合的彩色天气素材，可作为喂食卡的柔和天气背景图。"
    },
    {
      "src": "resources/base/media/partly_cloudy.png",
      "description": "云朵在前、太阳在后的彩色天气图标，可作为当前天气状态识别 glyph。"
    }
  ]
}

